CREATE TABLE `home_dashboard_items` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`audience_user_id` CHAR(36) CHARACTER SET ascii NULL,`kind` ENUM('action','change','follow','health') NOT NULL,`title` VARCHAR(255) NOT NULL,`reason` VARCHAR(500) NOT NULL,`route` VARCHAR(500) NOT NULL,`required_capability` VARCHAR(128) CHARACTER SET ascii NOT NULL,`priority` ENUM('overdue','blocking','high_risk','high_value','normal') NULL,`owner_label` VARCHAR(120) NULL,`due_at` DATETIME(3) NULL,`source_count` INT UNSIGNED NULL,`observed_at` DATETIME(3) NOT NULL,`severity` ENUM('info','warning','critical') NOT NULL DEFAULT 'info',`source_version` BIGINT UNSIGNED NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),KEY `idx_home_scope_kind_time` (`organization_id`,`workspace_id`,`kind`,`observed_at`,`id`),KEY `idx_home_audience_kind` (`audience_user_id`,`kind`,`observed_at`),KEY `idx_home_capability` (`organization_id`,`workspace_id`,`required_capability`),CONSTRAINT `fk_home_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE,CONSTRAINT `fk_home_workspace` FOREIGN KEY (`workspace_id`) REFERENCES `workspaces` (`id`) ON DELETE CASCADE,CONSTRAINT `fk_home_audience` FOREIGN KEY (`audience_user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
